-abstract public class JaninoEventEvaluatorBase<E> extends EventEvaluatorBase<E> {
-
-    static Class<?> EXPRESSION_TYPE = boolean.class;
-    static Class<?>[] THROWN_EXCEPTIONS = new Class[1];
